import{_ as i,o as n,c as o,a3 as a,j as t}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Integrated Autonomous Driving Kit","titleTemplate":false,"description":"A pre-integrated hardware and software development kit with an NVIDIA Jetson AGX Orin controller, 16-line LiDAR, four cameras, GNSS/INS, autonomy software and developer tools.","frontmatter":{"title":"Integrated Autonomous Driving Kit","titleTemplate":false,"description":"A pre-integrated hardware and software development kit with an NVIDIA Jetson AGX Orin controller, 16-line LiDAR, four cameras, GNSS/INS, autonomy software and developer tools.","status":"Product specification","content_type":"product","keywords":["autonomous driving development kit","Jetson AGX Orin","LiDAR","drive-by-wire chassis","campus autonomy"],"scope":"Prototype development, test validation and project integration for low-speed autonomy in controlled or semi-controlled sites","decision_summary":"Appropriate for teams that need a fast starting point for low-speed autonomous-driving development and validation; confirm configuration, chassis and operating boundary through a formal quotation.","best_for":["prototype development","low-speed campus transport","sensor/software integration","chassis integration","algorithm validation"],"not_for":["functional-safety or production certification by itself","vehicles without a confirmed drive-by-wire interface","demonstrations without a site or acceptance metric"],"next_action":"Send the vehicle, application, CAN signals and acceptance target to receive a configuration recommendation and formal quotation.","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20Integrated%20Autonomous%20Driving%20Kit%20inquiry","layout":"doc","sidebar":false,"aside":false,"outline":[2,3]},"headers":[],"relativePath":"en/solutions/integrated-autonomous-driving-kit.md","filePath":"en/solutions/integrated-autonomous-driving-kit.md","lastUpdated":1794216847000}'),r={name:"en/solutions/integrated-autonomous-driving-kit.md"};function s(d,e,l,c,u,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<div class="solution-hero"><a class="solution-language" href="/solutions/integrated-autonomous-driving-kit">中文版本</a><p class="solution-eyebrow">Integrated Autonomous Driving Kit</p><h1>A pre-integrated platform for autonomous vehicle development</h1><p class="solution-lead"> Start with compute, sensors, synchronized interfaces, an autonomous-driving software stack and developer tools that already work as one system. Spend your time on the vehicle, site and application. </p><div class="solution-actions"><a class="primary" href="mailto:support@wheelos.cn?subject=WheelOS%20Integrated%20Autonomous%20Driving%20Kit%20inquiry">Request a project quote</a><a href="/en/solutions/applications">Assess the application</a><a href="#specifications">View technical specifications</a></div><div class="solution-stats"><div class="solution-stat"><strong>200 TOPS</strong><span>AI compute, INT8</span></div><div class="solution-stat"><strong>4 + 1</strong><span>Surround cameras + 16-line LiDAR</span></div><div class="solution-stat"><strong>PTP/gPTP</strong><span>Hardware-level time sync</span></div><div class="solution-stat"><strong>From RMB 39,900</strong><span>Standard-kit reference price</span></div></div></div><div class="solution-callout"><p><strong>Intended use:</strong> The kit supports prototype development, test validation and project integration in campuses, industrial parks, scenic areas, ports, mines and similar controlled or semi-controlled environments. It is not supplied as a functionally safe or homologated production vehicle system. Final suitability depends on the vehicle, site and project requirements.</p></div><p>See <a href="/en/solutions/applications">short-distance transport applications</a> for scenario selection, commercial models and deployment gates.</p><h2 id="why-start-with-a-pre-integrated-kit" tabindex="-1">Why start with a pre-integrated kit <a class="header-anchor" href="#why-start-with-a-pre-integrated-kit" aria-label="Permalink to &quot;Why start with a pre-integrated kit&quot;">​</a></h2><div class="solution-grid"><div class="solution-card"><span class="solution-card__index">01</span><h3>Reduce integration work</h3><p>Compute, sensors, cabling and software modules share a defined interface, reducing hardware selection, driver adaptation and data-path debugging.</p></div><div class="solution-card"><span class="solution-card__index">02</span><h3>Keep the platform open</h3><p>Use the C++/Python SDK, API documentation, examples and CAN control interface to connect your own algorithms or operations system.</p></div><div class="solution-card"><span class="solution-card__index">03</span><h3>Investigate with evidence</h3><p>Record and replay Cyber Record data, inspect system state in DreamView and calibrate sensors as part of a traceable workflow.</p></div></div><h2 id="system-architecture" tabindex="-1">System architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System architecture&quot;">​</a></h2>',6),t("div",{class:"solution-flow",role:"img","aria-label":"System data flow from sensors and chassis through time synchronization and data interfaces, into localization, perception and planning, then to steering, drive and brake control"},[t("div",{class:"solution-flow__node"},[t("strong",null,"Sensors & chassis"),t("span",null,"LiDAR · Camera · GNSS/INS")]),t("span",{class:"solution-flow__arrow","aria-hidden":"true"},"→"),t("div",{class:"solution-flow__node"},[t("strong",null,"Sync & interfaces"),t("span",null,"PTP/gPTP · CAN FD · Ethernet")]),t("span",{class:"solution-flow__arrow","aria-hidden":"true"},"→"),t("div",{class:"solution-flow__node"},[t("strong",null,"Autonomy stack"),t("span",null,"Localization · Perception · Planning")]),t("span",{class:"solution-flow__arrow","aria-hidden":"true"},"→"),t("div",{class:"solution-flow__node"},[t("strong",null,"Vehicle actuation"),t("span",null,"Control · Steer · Drive · Brake")])],-1),a('<p>The kit combines multi-sensor data from LiDAR, cameras and GNSS/INS on an autonomous-driving domain controller. A standard vehicle interface connects the software stack to a drive-by-wire chassis. The stack can be based on Apollo or the WheelOS framework.</p><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h2><h3 id="autonomous-driving-domain-controller" tabindex="-1">Autonomous driving domain controller <a class="header-anchor" href="#autonomous-driving-domain-controller" aria-label="Permalink to &quot;Autonomous driving domain controller&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Specification</th></tr></thead><tbody><tr><td>Compute module</td><td>NVIDIA Jetson AGX Orin 32G</td></tr><tr><td>AI performance</td><td>200 TOPS INT8</td></tr><tr><td>Memory</td><td>32 GB LPDDR5, 204.8 GB/s</td></tr><tr><td>Storage</td><td>512 GB NVMe 2280 SSD</td></tr><tr><td>Core interfaces</td><td>2 × CAN with CAN FD support; 8 × GMSL2; 4 × Ethernet LiDAR ports</td></tr><tr><td>Additional interfaces</td><td>1 × USB 3.0; 3 × UART (RS232/485 configurable); GPIO; 1 × HDMI 2.0</td></tr><tr><td>Synchronization and reliability</td><td>Hardware PTP/gPTP master/slave; hardware watchdog; optional safety MCU</td></tr><tr><td>Power</td><td>9–36 V DC wide input with reverse-polarity and overvoltage protection</td></tr><tr><td>Power and environment</td><td>Approx. 80 W typical; -20°C to +60°C operating temperature; IP65</td></tr><tr><td>Cooling</td><td>Passive cooling plus intelligent fan assist</td></tr></tbody></table><h3 id="standard-sensor-suite" tabindex="-1">Standard sensor suite <a class="header-anchor" href="#standard-sensor-suite" aria-label="Permalink to &quot;Standard sensor suite&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sensor</th><th>Specification</th></tr></thead><tbody><tr><td>Primary LiDAR</td><td>16-line mechanical rotating scanner; 360° horizontal field of view; approx. 30° vertical field of view; ≥120 m at 10% reflectivity; 10 Hz; ±3 cm ranging accuracy; Ethernet; IP67</td></tr><tr><td>Surround cameras</td><td>4 × automotive-grade wide-angle cameras; ≥120° horizontal field of view; 1280 × 720; ≥30 fps; ≥100 dB HDR; GMSL2; IP67</td></tr><tr><td>Camera options</td><td>Optional 190° fisheye lens and 1920 × 1080 resolution</td></tr><tr><td>GNSS/INS</td><td>RTK GNSS + industrial IMU; GPS/GLONASS/BeiDou/Galileo; ≥100 Hz update rate; UART/CAN/Ethernet</td></tr><tr><td>Connectivity configuration</td><td>5G and Wi-Fi 6 router with 4 × gigabit Ethernet ports, subject to project confirmation</td></tr></tbody></table><h2 id="software-and-tools" tabindex="-1">Software and tools <a class="header-anchor" href="#software-and-tools" aria-label="Permalink to &quot;Software and tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>What is provided</th></tr></thead><tbody><tr><td>Base software</td><td>Ubuntu 20.04 / 22.04 LTS with real-time tuning; Apollo Cyber RT middleware</td></tr><tr><td>Perception</td><td>LiDAR and camera early/late fusion for 3D detection and tracking of vehicles, pedestrians and two-wheelers</td></tr><tr><td>Localization</td><td>Fusion of RTK-GNSS, IMU and LiDAR SLAM for high-rate, high-accuracy vehicle pose</td></tr><tr><td>Planning and control</td><td>HD-map point-to-point routing, static-obstacle avoidance and speed planning; PID/LQR control framework and CAN chassis interface</td></tr><tr><td>Tooling</td><td>Online/offline sensor calibration, DreamView visualization, Cyber Record recording and replay, HMI examples</td></tr><tr><td>Developer interfaces</td><td>C++/Python SDK for message subscription, data recording and control commands, with API documentation and examples</td></tr><tr><td>Simulation interfaces (optional)</td><td>Integration interfaces for CARLA, SVL and similar platforms for SIL/HIL validation</td></tr></tbody></table><h2 id="standard-deliverables" tabindex="-1">Standard deliverables <a class="header-anchor" href="#standard-deliverables" aria-label="Permalink to &quot;Standard deliverables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Included</th></tr></thead><tbody><tr><td>Hardware</td><td>1 × autonomous-driving domain controller; 1 × 16-line LiDAR; 4 × surround cameras; 1 × GNSS/INS with antenna; standard cable set and required accessories</td></tr><tr><td>Software</td><td>Preinstalled Ubuntu, Cyber RT, baseline autonomous-driving stack and development/debugging tools</td></tr><tr><td>Documentation</td><td>Product specification, user manual, quick-start guide and API/SDK reference</td></tr><tr><td>Support</td><td>One month of remote technical support from purchase, covering installation, configuration and basic use</td></tr></tbody></table><h2 id="chassis-and-integration-requirements" tabindex="-1">Chassis and integration requirements <a class="header-anchor" href="#chassis-and-integration-requirements" aria-label="Permalink to &quot;Chassis and integration requirements&quot;">​</a></h2><p>The vehicle should provide an open, stable and responsive CAN control interface with at least:</p><ul><li>Steering angle or steering-rate control</li><li>Throttle or drive-torque control</li><li>Brake-pressure or deceleration control</li><li>Gear state and required vehicle-status feedback</li><li>Confirmed communication protocol, signal definitions, units and safety limits</li></ul><p>Recommended integration sequence:</p><ol><li><strong>Scope and interface review:</strong> define the site, route, speed, vehicle constraints, acceptance criteria and chassis CAN capabilities.</li><li><strong>Bench and vehicle integration:</strong> install sensors, verify time synchronization, calibrate intrinsics/extrinsics and connect the chassis interface.</li><li><strong>Data and algorithm validation:</strong> record representative routes, replay data, run scenario tests and iterate parameters against measurable criteria.</li><li><strong>Controlled test and handover:</strong> validate baseline functions at a controlled site, complete documentation, training and issue closure.</li></ol><h2 id="services-and-customization" tabindex="-1">Services and customization <a class="header-anchor" href="#services-and-customization" aria-label="Permalink to &quot;Services and customization&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Included</th><th>Scope</th></tr></thead><tbody><tr><td>Standard documentation and remote support</td><td>Yes</td><td>One month of remote technical support</td></tr><tr><td>On-site deployment and precision calibration</td><td>Optional</td><td>Hardware installation, sensor intrinsics/extrinsics, vehicle dynamics parameters, system integration and baseline demonstration</td></tr><tr><td>Customized training</td><td>Optional</td><td>System architecture, algorithms, secondary development, test operations</td></tr><tr><td>Custom feature development</td><td>Optional</td><td>Algorithm modules or feature extensions for a specific application</td></tr><tr><td>HD map service</td><td>Optional</td><td>Campus or site map acquisition, production and maintenance</td></tr><tr><td>Simulation testing service</td><td>Optional</td><td>Algorithm testing and validation on simulation platforms</td></tr></tbody></table><h2 id="pricing-and-inquiry" tabindex="-1">Pricing and inquiry <a class="header-anchor" href="#pricing-and-inquiry" aria-label="Permalink to &quot;Pricing and inquiry&quot;">​</a></h2><p>The standard-kit reference price is <strong>from RMB 39,900</strong>. The final price depends on configuration, destination, taxes, freight, chassis adaptation and optional services, and is confirmed in a formal quotation.</p><div class="solution-contact"><a href="mailto:support@wheelos.cn?subject=WheelOS%20Integrated%20Autonomous%20Driving%20Kit%20inquiry"><small>Project inquiries</small><strong>support@wheelos.cn</strong></a><a href="tel:+8618320813902"><small>Phone</small><strong>+86 183 2081 3902</strong></a><div><small>Headquarters</small><strong>Floor 11, Building A, Pingshan Chengtou Zhiyuan, No. 37 Cuijing Road, Pingshan District, Shenzhen, China</strong></div></div><div class="solution-cta"><div><h2>Ready to scope your autonomous vehicle project?</h2><p>Send the vehicle type, application, chassis interface and timeline. We will respond with a recommended configuration and the next integration questions.</p></div><div class="solution-actions"><a class="primary" href="mailto:support@wheelos.cn?subject=WheelOS%20Integrated%20Autonomous%20Driving%20Kit%20inquiry">Contact WheelOS</a></div></div><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><h3 id="is-a-vehicle-chassis-included" tabindex="-1">Is a vehicle chassis included? <a class="header-anchor" href="#is-a-vehicle-chassis-included" aria-label="Permalink to &quot;Is a vehicle chassis included?&quot;">​</a></h3><p>No. The kit includes the domain controller, sensors, software and support. The vehicle project supplies a compatible drive-by-wire chassis and CAN interface.</p><h3 id="can-the-kit-be-integrated-with-our-existing-vehicle" tabindex="-1">Can the kit be integrated with our existing vehicle? <a class="header-anchor" href="#can-the-kit-be-integrated-with-our-existing-vehicle" aria-label="Permalink to &quot;Can the kit be integrated with our existing vehicle?&quot;">​</a></h3><p>We first review the chassis protocol, control signals, response behavior, installation space and vehicle safety limits. For an efficient quotation, share the CAN DBC, vehicle dimensions, sensor-placement constraints and target operating scenario.</p><h3 id="can-it-be-used-in-a-production-vehicle-program" tabindex="-1">Can it be used in a production vehicle program? <a class="header-anchor" href="#can-it-be-used-in-a-production-vehicle-program" aria-label="Permalink to &quot;Can it be used in a production vehicle program?&quot;">​</a></h3><p>The kit is intended for prototype development, test validation and controlled-site integration. A production program requires separate functional-safety, regulatory, reliability and supply-chain qualification.</p><h3 id="do-you-work-with-international-customers" tabindex="-1">Do you work with international customers? <a class="header-anchor" href="#do-you-work-with-international-customers" aria-label="Permalink to &quot;Do you work with international customers?&quot;">​</a></h3><p>Yes. English product documentation and international project inquiries are supported. Delivery scope, language support, on-site service and applicable regulations are confirmed during project evaluation.</p>',30)])])}const g=i(r,[["render",s]]);export{m as __pageData,g as default};
